{"content":"namespace LetUsCook.AutoWrongCensus.Options;

/// <summary>
/// Maps the <c>census</c> / <c>pairs</c> positional CLI syntax into options.
/// Unknown or malformed invocations leave <see cref="AutoWrongCensusOptions.Command"/> empty and the
/// runner reports the usage on stderr with exit 1.
/// </summary>
public static class CommandLineArgumentParser
{
	public static Dictionary<string, string?> Parse(string[] args)
	{
		ArgumentNullException.ThrowIfNull(args);
		var dict = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);

		if (args.Length == 0 || args[0] is not ("census" or "pairs"))
		{
			return dict;
		}

		if (args[0].Equals("census", StringComparison.OrdinalIgnoreCase) && args.Length == 2)
		{
			dict["AutoWrongCensus:Command"] = "census";
			dict["AutoWrongCensus:TracePath"] = args[1];
			return dict;
		}

		if (args[0].Equals("pairs", StringComparison.OrdinalIgnoreCase) && args.Length == 3)
		{
			dict["AutoWrongCensus:Command"] = "pairs";
			dict["AutoWrongCensus:CensusTsvPath"] = args[1];
			dict["AutoWrongCensus:TracePath"] = args[2];
			return dict;
		}

		return new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);
	}
}
