/// <summary>
/// Console output sinks for the auto-wrong census: the machine-readable TSV on stdout, the summary
/// and diagnostics on stderr. Defaults to the process streams; tests inject <see cref="System.IO.TextWriter"/>s.
/// </summary>
/// <param name="Output">TSV sink.</param>
/// <param name="Error">Summary/diagnostic sink.</param>
public sealed record OutputWriters(System.IO.TextWriter Output, System.IO.TextWriter Error);

/// <summary>
/// Builds the auto-wrong census host: production FDC normalizer + lexicon, the exact-overrides key set,
/// the classifier, and the runner that drives them.
/// </summary>
public static class AutoWrongCensusHostBuilderFactory
{
	/// <summary>Creates the host builder for one census/pairs invocation.</summary>
	/// <param name="args">Raw CLI arguments.</param>
	/// <param name="output">Optional TSV sink override (tests).</param>
	/// <param name="error">Optional summary sink override (tests).</param>
	/// <returns>A configured <see cref="Microsoft.Extensions.Hosting.HostApplicationBuilder"/>.</returns>
	public static Microsoft.Extensions.Hosting.HostApplicationBuilder Create(string[] args, System.IO.TextWriter? output = null, System.IO.TextWriter? error = null)
	{
		var builder = Microsoft.Extensions.Hosting.Host.CreateApplicationBuilder(args);

		builder.Configuration.AddInMemoryCollection(CommandLineArgumentParser.Parse(args));
		builder.Services.Configure<AutoWrongCensusOptions>(builder.Configuration.GetSection(AutoWrongCensusOptions.SectionName));

		var debug = Array.Exists(args, a => a.Equals("--debug", StringComparison.OrdinalIgnoreCase) || a.Equals("--verbose", StringComparison.OrdinalIgnoreCase));
		builder.Logging.ClearProviders();
		builder.Logging.AddConsole();
		builder.Logging.SetMinimumLevel(debug ? Microsoft.Extensions.Logging.LogLevel.Debug : Microsoft.Extensions.Logging.LogLevel.Error);
		builder.Logging.AddFilter("Microsoft", Microsoft.Extensions.Logging.LogLevel.Warning);

		builder.Services.AddSingleton<AutoWrongCensusOptions>(_ =>
			new AutoWrongCensusOptions
			{
				Command = CommandLineArgumentParser.Parse(args).TryGetValue("AutoWrongCensus:Command", out var cmd) && cmd is { } c ? c : string.Empty,
				TracePath = CommandLineArgumentParser.Parse(args).TryGetValue("AutoWrongCensus:TracePath", out var tp) && tp is { } t ? t : string.Empty,
				CensusTsvPath = CommandLineArgumentParser.Parse(args).TryGetValue("AutoWrongCensus:CensusTsvPath", out var ct) && ct is { } c2 ? c2 : string.Empty,
			});

		builder.Services.AddSingleton(sp =>
		{
			var options = sp.GetRequiredService<Microsoft.Extensions.Options.IOptions<AutoWrongCensusOptions>>().Value;
			return new OutputWriters(output ?? System.Console.Out, error ?? System.Console.Error);
		});

		builder.Services.AddSingleton<LetUsCook.Fdc.Lexicon.FdcNormalizer>();
		builder.Services.AddSingleton<ExactOverrideKeyIndex>();
		builder.Services.AddSingleton<AutoWrongClassifier>();
		builder.Services.AddSingleton<AutoWrongCensusRunner>();
		builder.Services.AddSingleton<AutoWrongCensusHostedService>();
		builder.Services.AddHostedService(sp => sp.GetRequiredService<AutoWrongCensusHostedService>());

		return builder;
	}
}
