{"content":"using System.Text.RegularExpressions;

using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line: relation (accepted row vs key row) and site (decision path).
/// Every comparison goes through the production helpers (<see cref="FdcNormalizer"/>, <see cref="FdcMatcher"/>,
/// <see cref="FdcDescriptionParser"/>, <see cref="IngredientLineResolver"/>) — never a copy of their logic.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	private const string RelationNoLabel = "no-label";
	private const string RelationPackUnitState = "pack-unit-state";
	private const string RelationCompoundHeadLost = "compound-head-lost";
	private const string RelationStateMismatch = "state-mismatch";
	private const string RelationRowChoiceTier = "row-choice-tier";
	private const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";
	private const string RelationSiblingFood = "sibling-food";
	private const string RelationOther = "other";

	private const string SiteRanker = "ranker";
	private const string SiteReuse = "reuse";
	private const string SiteOverride = "override";
	private const string SiteCurated = "curated";

	private static readonly FrozenSet<string> CompoundOrOtherRoutes = FrozenSet.Create(["compound", "other"]);

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;
	private readonly List<string> _singleToken = new();

	private AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	/// <summary>Creates the classifier over the production normalizer and the exact-overrides key index.</summary>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
		: this()
	{
	}

	/// <summary>Classifies one auto-wrong line into its relation and site.</summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The classification row.</returns>
	/// <exception cref="InvalidOperationException">When the atom path is not a known site.</exception>
	public ClassificationResult Classify(TraceLine line)
	{
		var atom = AcceptedAtom(line);
		var site = ResolveSite(line, atom);

		var keyDesc = First(line.ExpectedDescriptions);
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return NewResult(line, RelationNoLabel, site, null, null, null, null, null, null, null, null, null, null, null, null, null);
		}

		var acceptedDesc = First(line.ActualDescriptions);
		if (string.IsNullOrWhiteSpace(acceptedDesc))
		{
			return NewResult(line, RelationOther, site, null, null, null, null, null, null, null, null, null, null, null, null, "actualDescriptions");
		}

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		var keyHead = FdcDescriptionParser.Parse(keyDesc, ToDataset(First(line.ExpectedDataTypes))).HeadTerm;
		var acceptedHead = FdcDescriptionParser.Parse(acceptedDesc, ToDataset(First(line.ActualDataTypes))).HeadTerm;
		var keyHeadTokens = Phrase(keyHead);
		var acceptedHeadTokens = Phrase(acceptedHead);
		var parsedNameTokens = Phrase(atom.ParsedName);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		var relation = RelationFor(line, atom, keyDesc, acceptedDesc, keyTokens, acceptedTokens, keyState, acceptedState, keyHeadTokens, acceptedHeadTokens, parsedNameTokens, keyHeadPhrase);

		return NewResult(
			line,
			relation,
			site,
			site == SiteOverride ? (_overrideKeys.IsKey(line.RawText) ? "yes" : "no") : null,
			First(line.ExpectedDataTypes),
			First(line.ActualDataTypes),
			AcceptedState.ToString(),
			KeyStateOf(line, keyDesc, acceptedDesc, keyState, acceptedState),
			atom.ParsedName,
			string.Join(' ', keyHeadPhrase),
			acceptedDesc,
			keyDesc,
			line.RawText,
			relation == RelationSameHeadOtherQualifier ? QualifierDiff(keyDesc, acceptedDesc) : null);
	}

	/// <summary>Leading tokens of a normalised head phrase: stop before the first state/modifier token.</summary>
	/// <param name="tokens">Normalised head tokens.</param>
	/// <returns>The leading (non-state) tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		var phrase = new List<string>();
		foreach (var token in tokens)
		{
			if (IsStateToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	private static string KeyStateOf(TraceLine line, string keyDesc, string acceptedDesc, FoodState keyState, FoodState acceptedState) => acceptedState.ToString();

	private static FoodState CombinedState(IReadOnlyList<string> tokens)
	{
		_singleToken.Clear();
		_singleToken.AddRange(tokens);
		return FdcMatcher.ExtractCandidateState(_singleToken) | FdcMatcher.ExtractCandidateSatisfiers(_singleToken);
	}

	private static bool IsStateToken(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private static IReadOnlyList<string> Phrase(string? text)
	{
		var tokens = new List<string>();
		foreach (var token in _normalizer.NormalizeToTokens(text))
		{
			tokens.Add(IngredientLineResolver.SingularizeToken(token));
		}

		return tokens;
	}

	private static string? First(IReadOnlyList<string> values) =>
		values.Count > 0 ? values[0] : string.Empty;

	private static FdcDataset ToDataset(string? tier) =>
		string.IsNullOrWhiteSpace(tier) ? FdcDataset.None : Enum.Parse<FdcDataset>(tier, ignoreCase: true);

	private static TraceAtom? AcceptedAtom(TraceLine line)
	{
		foreach (var atom in line.Atoms)
		{
			if (atom.Outcome == "accepted")
			{
				return atom;
			}
		}

		return line.Atoms.Count > 0 ? line.Atoms[0] : null;
	}

	private static string ResolveSite(TraceLine line, TraceAtom? atom)
	{
		var path = atom?.Path ?? string.Empty;
		if (path == "ranker")
		{
			return atom!.Reused ? SiteReuse : SiteRanker;
		}

		if (path == "override")
		{
			return SiteOverride;
		}

		if (path == "curated")
		{
			return SiteCurated;
		}

		throw new InvalidOperationException($"unknown resolver path '{path}' on {line.HoldoutId}:{line.LineIndex}");
	}

	private static string RelationFor(
		TraceLine line,
		TraceAtom atom,
		string keyDesc,
		string acceptedDesc,
		IReadOnlyList<string> keyTokens,
		IReadOnlyList<string> acceptedTokens,
		FoodState keyState,
		FoodState acceptedState,
		IReadOnlyList<string> keyHeadTokens,
		IReadOnlyList<string> acceptedHeadTokens,
		IReadOnlyList<string> parsedNameTokens,
		IReadOnlyList<string> keyHeadPhrase)
	{
		if (PackUnitRegex.IsMatch(line.RawText)
			&& keyState.HasFlag(FoodState.Canned)
			&& acceptedState.HasFlag(FoodState.Canned) == false)
		{
			return RelationPackUnitState;
		}

		if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return RelationCompoundHeadLost;
		}

		if (HeadsAgree(keyHeadTokens, acceptedHeadTokens))
		{
			if (keyState != acceptedState)
			{
				return RelationStateMismatch;
			}

			if (string.IsNullOrWhiteSpace(First(line.ActualDataTypes)))
			{
				return RelationOther;
			}

			if (First(line.ExpectedDataTypes) != First(line.ActualDataTypes))
			{
				return RelationRowChoiceTier;
			}

			return RelationSameHeadOtherQualifier;
		}

		return RelationSiblingFood;
	}

	private static bool HeadsAgree(IReadOnlyList<string> keyHeadTokens, IReadOnlyList<string> acceptedHeadTokens) =>
		keyHeadTokens.SequenceEqual(acceptedHeadTokens, StringComparer.OrdinalIgnoreCase);

	private static string? QualifierDiff(string keyDesc, string acceptedDesc)
	{
		var keyQualifiers = FdcDescriptionParser.Parse(keyDesc, FdcDataset.None).Qualifiers;
		var acceptedQualifiers = FdcDescriptionParser.Parse(acceptedDesc, FdcDataset.None).Qualifiers;
		var keySet = new HashSet<string>(keyQualifiers.Select(IngredientLineResolver.SingularizeToken), StringComparer.OrdinalIgnoreCase);
		var acceptedSet = new HashSet<string>(acceptedQualifiers.Select(IngredientLineResolver.SingularizeToken), StringComparer.OrdinalIgnoreCase);
		var diff = new List<string>();
		foreach (var extra in keySet.Except(acceptedSet).OrderBy(w => w, StringComparer.Ordinal))
		{
			diff.Add($"key-only:{extra}");
		}

		foreach (var extra in acceptedSet.Except(keySet).OrderBy(w => w, StringComparer.Ordinal))
		{
			diff.Add($"accepted-only:{extra}");
		}

		return string.Join(',', diff);
	}

	private static ClassificationResult NewResult(
		TraceLine line,
		string relation,
		string site,
		string? overrideKey,
		string? acceptedTier,
		string? keyTier,
		string acceptedState,
		string keyState,
		string parsedName,
		string keyHead,
		string acceptedDesc,
		string keyDesc,
		string rawText,
		string? missingField,
		string? qualifierDiff)
	{
		return new ClassificationResult(
			line.HoldoutId,
			line.LineIndex,
			line.Set,
			relation,
			site,
			overrideKey,
			acceptedTier,
			keyTier,
			acceptedState,
			keyState,
			parsedName,
			keyHead,
			acceptedDesc,
			keyDesc,
			rawText,
			missingField,
			qualifierDiff);
	}
}
