{"content":"using System.Text.RegularExpressions;

using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

using LetUsCook.AutoWrongCensus.Models;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line: accepted row (<c>actual*</c>) vs key row (<c>expected*</c>)
/// relation, and the decision site. All state/head/singularisation logic flows through the production
/// helpers (<c>FdcNormalizer</c>, <c>FdcMatcher.ExtractCandidateState/Satisfiers</c>,
/// <c>FdcDescriptionParser</c>, <c>IngredientLineResolver.SingularizeToken</c>) — no copies (F-428 D-014).
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation classes, in the brief's first-match order.</summary>
	public const string NoLabel = "no-label";
	public const string PackUnitState = "pack-unit-state";
	public const string CompoundHeadLost = "compound-head-lost";
	public const string StateMismatch = "state-mismatch";
	public const string RowChoiceTier = "row-choice-tier";
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";
	public const string SiblingFood = "sibling-food";
	public const string Other = "other";

	private static readonly FoodState CannedMask = FoodState.Canned;

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;
	private readonly List<string> _singleToken = [];

	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	/// <summary>Matches a can/jar unit in the raw line text.</summary>
	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>Classifies one trace line into its relation, site and row-level fields.</summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();

		var keyDesc = line.ExpectedDescriptions.FirstOrDefault(d => !string.IsNullOrWhiteSpace(d)) ?? string.Empty;
		var acceptedDesc = line.ActualDescriptions.FirstOrDefault(d => !string.IsNullOrWhiteSpace(d)) ?? string.Empty;
		var keyTier = line.ExpectedDataTypes.FirstOrDefault() ?? string.Empty;
		var acceptedTier = line.ActualDataTypes.FirstOrDefault() ?? string.Empty;

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			RawText = line.RawText,
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyDesc = keyDesc,
			AcceptedDesc = acceptedDesc,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = string.Empty,
			KeyState = string.Empty,
			KeyHead = string.Empty,
		};

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			result.Relation = NoLabel;
			return result;
		}

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		result.AcceptedState = acceptedState.ToString();
		result.KeyState = keyState.ToString();

		var keyHeadPhrase = KeyHeadPhrase(keyTokens);
		result.KeyHead = string.Join(' ', keyHeadPhrase);
		var parsedTokens = SingularPhrase(atom?.ParsedName);
		var keyHeadParsed = FdcDescriptionParser.Parse(keyDesc, ToDataset(keyTier));
		var acceptedHeadParsed = acceptedDesc.Length > 0 ? FdcDescriptionParser.Parse(acceptedDesc, ToDataset(acceptedTier)) : null;

		var headsAgree = acceptedHeadParsed is not null
			&& PhraseEquals(SingularPhrase(keyHeadParsed.HeadTerm), SingularPhrase(acceptedHeadParsed.HeadTerm));

		if (PackUnitRegex.IsMatch(line.RawText)
			&& keyState.HasFlag(CannedMask)
			&& !acceptedState.HasFlag(CannedMask))
		{
			result.Relation = PackUnitState;
		}
		else if (keyHeadPhrase.Count >= 2
			&& parsedTokens.Count == 1
			&& string.Equals(parsedTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			result.Relation = CompoundHeadLost;
		}
		else if (!headsAgree)
		{
			result.Relation = SiblingFood;
		}
		else if (keyState != acceptedState)
		{
			result.Relation = StateMismatch;
		}
		else if (string.IsNullOrWhiteSpace(acceptedTier) || string.IsNullOrWhiteSpace(keyTier))
		{
			result.Relation = Other;
			result.MissingField = string.IsNullOrWhiteSpace(acceptedTier) ? "actualDataTypes" : "expectedDataTypes";
		}
		else if (string.CompareOrdinal(keyTier, acceptedTier) != 0)
		{
			result.Relation = RowChoiceTier;
		}
		else
		{
			result.Relation = SameHeadOtherQualifier;
			result.KeyOnlyQualifiers = KeyOnlyQualifiers(keyHeadParsed, acceptedHeadParsed);
			result.AcceptedOnlyQualifiers = AcceptedOnlyQualifiers(keyHeadParsed, acceptedHeadParsed);
		}

		var site = atom is null ? string.Empty : atom.Path switch
		{
			"override" => "override",
			"curated" => "curated",
			"ranker" => atom.Reused ? "reuse" : "ranker",
			_ => string.Empty,
		};
		result.Site = site;
		if (site.Length > 0)
		{
			if (site == "override")
			{
				result.OverrideKey = _overrideKeys.Contains(line.RawText) ? "yes" : "no";
			}
		}
		else
		{
			result.Site = string.Empty;
		}

		return result;
	}

	/// <summary>Combined production state mask: candidate state ∪ satisfiers.</summary>
	/// <param name="tokens">Normalized tokens of one description.</param>
	/// <returns>The combined <see cref="FoodState"/> mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens)
	{
		FdcMatcher.ExtractCandidateState(tokens);
		return FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);
	}

	/// <summary>Key head phrase: leading tokens up to the first production state/modifier word.</summary>
	/// <param name="tokens">Normalized key tokens.</param>
	/// <returns>The head phrase tokens; empty when the description carries no head.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		var phrase = new List<string>();
		foreach (var token in tokens)
		{
			if (IsStateWord(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>Whether a token carries food identity or is a production state/modifier word.</summary>
	/// <param name="token">One normalized token.</param>
	/// <returns>True when the token is a state/modifier word and therefore not part of the head phrase.</returns>
	private bool IsStateWord(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	/// <summary>Singularised token phrase of a description-derived head term.</summary>
	/// <param name="headTerm">The head term.</param>
	/// <returns>Normalized singularised tokens.</returns>
	private IReadOnlyList<string> SingularPhrase(string? headTerm)
	{
		return _normalizer.NormalizeToTokens(headTerm).Select(IngredientLineResolver.SingularizeToken).ToArray();
	}

	/// <summary>Whether two singularised head phrases agree.</summary>
	/// <param name="left">First head tokens.</param>
	/// <param name="right">Second head tokens.</param>
	/// <returns>True when the phrases are equal ignoring case.</returns>
	public static bool PhraseEquals(IReadOnlyList<string> left, IReadOnlyList<string> right)
	{
		return left.SequenceEqual(right, StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>Key-only qualifier tokens for a same-head relation.</summary>
	/// <param name="key">Key parsed description.</param>
	/// <param name="accepted">Accepted parsed description.</param>
	/// <returns>The key-only qualifier tokens.</returns>
	private IReadOnlyList<string>? KeyOnlyQualifiers(ParsedFdcDescription key, ParsedFdcDescription? accepted)
	{
		var keyWords = key.Qualifiers.Select(IngredientLineResolver.SingularizeToken).ToHashSet(StringComparer.OrdinalIgnoreCase);
		var acceptedWords = accepted?.Qualifiers.Select(IngredientLineResolver.SingularizeToken).ToHashSet(StringComparer.OrdinalIgnoreCase) ?? new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		var keyOnly = keyWords.Except(acceptedWords).OrderBy(w => w, StringComparer.Ordinal).ToList();
		return keyOnly;
	}

	/// <summary>Accepted-only qualifier tokens for a same-head relation.</summary>
	/// <param name="key">Key parsed description.</param>
	/// <param name="accepted">Accepted parsed description.</param>
	/// <returns>The accepted-only qualifier tokens.</returns>
	private IReadOnlyList<string>? AcceptedOnlyQualifiers(ParsedFdcDescription key, ParsedFdcDescription? accepted)
	{
		var keyWords = key.Qualifiers.Select(IngredientLineResolver.SingularizeToken).ToHashSet(StringComparer.OrdinalIgnoreCase);
		var acceptedWords = accepted?.Qualifiers.Select(IngredientLineResolver.SingularizeToken).ToHashSet(StringComparer.OrdinalIgnoreCase) ?? new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		var acceptedOnly = acceptedWords.Except(keyWords).OrderBy(w => w, StringComparer.Ordinal).ToList();
		return acceptedOnly;
	}

	/// <summary>Maps a dataset tier name to the FDC dataset enum.</summary>
	/// <param name="tier">Dataset tier name.</param>
	/// <returns>The mapped dataset; <see cref="FdcDataset.None"/> when unknown.</returns>
	private static FdcDataset ToDataset(string tier)
	{
		return Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;
	}
}
