{"content":"using System.Text.RegularExpressions;

using LetUsCook.Fdc;
using LetUsCook.Fdc.Classification;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line by accepted-row vs key-row <c>relation</c> and decision-site
/// <c>site</c>, calling the production helpers (<see cref="FdcNormalizer"/>, <see cref="FdcMatcher"/>,
/// <see cref="FdcDescriptionParser"/>, <see cref="IngredientLineResolver"/>) — never a copy of their logic
/// (F-428 D-014).
/// </summary>
public sealed partial class AutoWrongClassifier
{
	private static readonly Regex PackUnitRegex = new(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase | RegexOptions.Compiled);

	private readonly FdcNormalizer _normalizer;
	private readonly List<string> _singleToken = [];

	private AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer;
		OverrideKeys = overrideKeys;
	}

	/// <summary>Shared key index for override checks.</summary>
	public ExactOverrideKeyIndex OverrideKeys { get; }

	/// <summary>Classifies a single line; only called for <c>auto == true && correct == false</c> lines.</summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The relation/site result.</returns>
	public ClassificationResult Classify(Models.TraceLine line)
	{
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();
		if (atom is null)
		{
			throw new InvalidOperationException($"Trace line '{line.HoldoutId}'#{line.LineIndex} has no atoms to classify against.");
		}

		var keyDesc = line.ExpectedDescriptions.FirstOrDefault(d => !string.IsNullOrWhiteSpace(d)) ?? string.Empty;
		var acceptedDesc = line.ActualDescriptions.FirstOrDefault(d => !string.IsNullOrWhiteSpace(d)) ?? string.Empty;
		var keyTier = line.ExpectedDataTypes.FirstOrDefault(t => !string.IsNullOrWhiteSpace(t)) ?? string.Empty;
		var acceptedTier = line.ActualDataTypes.FirstOrDefault(t => !string.IsNullOrWhiteSpace(t)) ?? string.Empty;

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyParsed = Parse(keyDesc, keyTier);
		var acceptedParsed = acceptedDesc.Length > 0 ? Parse(acceptedDesc, acceptedTier) : null;

		var keyHead = keyParsed is null ? string.Empty : keyParsed.HeadTerm;
		var acceptedHead = acceptedParsed is null ? string.Empty : acceptedParsed.HeadTerm;
		var keyHeadTokens = SingularPhrase(keyHead);
		var acceptedHeadTokens = acceptedParsed is null ? [] : SingularPhrase(acceptedHead);

		var parsedNameTokens = SingularPhrase(atom.ParsedName);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		var relation = "other";
		var missingField = (string?)null;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = "no-label";
		}
		else if (PackUnitRegex.IsMatch(line.RawText) && (keyState & FoodState.Canned) != FoodState.None && (acceptedState & FoodState.Canned) == FoodState.None)
		{
			relation = "pack-unit-state";
		}
		else if (keyHeadPhrase.Count >= 2 && parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			relation = "compound-head-lost";
		}
		else if (acceptedParsed is null)
		{
			relation = "other";
			missingField = acceptedDesc.Length == 0 ? "actualDescriptions" : "actualDataTypes";
		}
		else if (keyHeadTokens.SequenceEqual(acceptedHeadTokens, StringComparer.OrdinalIgnoreCase))
		{
			if (keyState != acceptedState)
			{
				relation = "state-mismatch";
			}
			else if (keyTier.Length == 0 || acceptedTier.Length == 0)
			{
				relation = "other";
				missingField = keyTier.Length == 0 ? "expectedDataTypes" : "actualDataTypes";
			}
			else if (keyTier != acceptedTier)
			{
				relation = "row-choice-tier";
			}
			else
			{
				relation = "same-head-other-qualifier";
			}
		}
		else
		{
			relation = "sibling-food";
		}

		var site = atom.Path switch
		{
			"ranker" => atom.Reused ? "reuse" : "ranker",
			"override" => "override",
			"curated" => "curated",
			_ => string.Empty,
		};

		var overrideKey = atom.Path == "override"
			? (OverrideKeys.IsKey(NormalizeForOverrideKey(line.RawText)) ? "yes" : "no")
			: string.Empty;

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom.ParsedName,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = relation == "same-head-other-qualifier"
				? keyParsed!.Qualifiers.Where(q => !acceptedParsed!.Qualifiers.Contains(q, StringComparer.OrdinalIgnoreCase)).Distinct().ToList()
				: null,
			AcceptedOnlyQualifiers = relation == "same-head-other-qualifier"
				? acceptedParsed!.Qualifiers.Where(q => !keyParsed!.Qualifiers.Contains(q, StringComparer.OrdinalIgnoreCase)).Distinct().ToList()
				: null,
		};
	}

	/// <summary>Computes the key head phrase: normalized tokens up to the first production state/modifier word.</summary>
	/// <param name="tokens">Normalized key tokens.</param>
	/// <returns>The leading head-phrase tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		var phrase = new List<string>();
		foreach (var token in tokens)
		{
			if (IsStateWord(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>Whether a single normalized token is a production state/modifier word.</summary>
	/// <param name="token">The normalized token.</param>
	/// <returns>True when the token carries state.</returns>
	private bool IsStateWord(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_single.Clear();
		_single.Add(token);
		return FdcMatcher.ExtractCandidateState(_single) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_single) != FoodState.None;
	}

	private static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	private static FdcDescriptionParser.ParsedFdcDescription Parse(string description, string datasetTier)
	{
		var dataset = Enum.TryParse<FdcDataset>(datasetTier, ignoreCase: true, out var parsed) ? parsed : FdcDataset.None;
		return FdcDescriptionParser.Parse(description, dataset);
	}

	private static IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static string NormalizeForOverrideKey(string rawText)
	{
		var trimmed = rawText.Trim().ToLowerInvariant();
		var cut = trimmed.IndexOf('(', StringComparison.Ordinal);
		return cut >= 0 ? trimmed[..cut].Trim() : trimmed;
	}
}
