{"content":"using System.Text.RegularExpressions;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

using LetUsCook.AutoWrongCensus.Models;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line: relation (accepted row vs key row) and site (decision path).
/// All comparisons go through the production helpers (<c>FdcNormalizer</c>, <c>FdcDescriptionParser</c>,
/// <c>FdcMatcher</c>, <c>IngredientLineResolver</c>) — no copy of the matching logic.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	private static readonly Regex PackUnitRegex = new(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase | RegexOptions.Compiled);

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;
	private readonly string?[] _singleTokenScratch = new string[1];

	/// <summary>Creates the classifier over the production normalizer and the override key set.</summary>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	/// <summary>
	/// Classifies one line. Only the <c>auto == true && correct == false</c> lines are expected here;
	/// the runner filters before calling.
	/// </summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The relation/site classification.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();
		var site = AtomSite(atom);
		var overrideKey = site == "override" && atom is not null ? (IsOverrideKey(line.RawText) ? "yes" : "no") : string.Empty;

		var keyDesc = line.ExpectedDescriptions.FirstOrDefault(d => !string.IsNullOrWhiteSpace(d)) ?? string.Empty;
		var acceptedDesc = line.ActualDescriptions.FirstOrDefault(d => !string.IsNullOrWhiteSpace(d)) ?? string.Empty;
		var keyTier = line.ExpectedDataTypes.FirstOrDefault(t => !string.IsNullOrWhiteSpace(t)) ?? string.Empty;
		var acceptedTier = line.ActualDataTypes.FirstOrDefault(t => !string.IsNullOrWhiteSpace(t)) ?? string.Empty;

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyDesc = keyDesc,
			AcceptedDesc = acceptedDesc,
			RawText = line.RawText,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			OverrideKey = overrideKey,
			AcceptedState = StateName(CombinedStateTokens(acceptedDesc)),
			KeyState = StateName(CombinedStateTokens(keyDesc)),
			KeyHead = string.Join(' ', KeyHeadPhrase(NormalizeTokens(keyDesc))),
			Site = site,
		};

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			result.Relation = RelationNames.NoLabel;
			return result;
		}

		var keyTokens = NormalizeTokens(keyDesc);
		var acceptedTokens = NormalizeTokens(acceptedDesc);
		var keyState = CombinedStateTokens(keyDesc);
		var acceptedState = CombinedStateTokens(acceptedDesc);
		var headsAgree = HeadsAgree(keyTokens, acceptedTokens);

		if (PackUnitRegex.IsMatch(line.RawText) && (keyState & FoodState.Canned) != FoodState.None && (acceptedState & FoodState.Canned) == FoodState.None)
		{
			result.Relation = RelationNames.PackUnitState;
			return result;
		}

		var parsedNameTokens = NormalizeTokens(atom?.ParsedName);
		var keyHeadTokens = KeyHeadPhrase(keyTokens);
		if (keyHeadTokens.Count >= 2
			&& parsedNameTokens.Count == 1
				&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadTokens[0]), StringComparison.OrdinalIgnoreCase))
		{
			result.Relation = RelationNames.CompoundHeadLost;
			return result;
		}

		if (string.IsNullOrWhiteSpace(acceptedDesc))
		{
			result.MissingField = "actualDescriptions";
			result.Relation = RelationNames.Other;
			return result;
		}

		if (headsAgree)
		{
			if (keyState != acceptedState)
			{
				result.Relation = RelationNames.StateMismatch;
				return result;
			}

			if (string.IsNullOrWhiteSpace(acceptedTier) || string.IsNullOrWhiteSpace(keyTier))
			{
				result.MissingField = "actualDataTypes";
				result.Relation = RelationNames.Other;
				return result;
			}

			if (!string.Equals(acceptedTier, keyTier, StringComparison.OrdinalIgnoreCase))
			{
				result.Relation = RelationNames.RowChoiceTier;
				return result;
			}

			result.Relation = RelationNames.SameHeadOtherQualifier;
			result.KeyOnlyQualifiers = QualifierDiff(NormalizeTokens(keyDesc), NormalizeTokens(acceptedDesc));
			return result;
		}

		result.Relation = RelationNames.SiblingFood;
		return result;
	}

	/// <summary>Head-phrase tokens of a key description: leading tokens up to the first production state/modifier word.</summary>
	/// <param name="tokens">Normalized key tokens.</param>
	/// <returns>The head-phrase token list.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		var phrase = new List<string>();
		foreach (var token in tokens)
		{
			if (CarriesStateToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	private string AtomSite(TraceAtom? atom)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		return atom.Path switch
		{
			"ranker" => atom.Reused ? "reuse" : "ranker",
			"override" => "override",
			"curated" => "curated",
			_ => string.Empty,
		};
	}

	private bool IsOverrideKey(string rawText)
	{
		var normalized = NormalizeOverrideKey(rawText);
		return _overrideKeys.IsKey(normalized);
	}

	private static string NormalizeOverrideKey(string rawText)
	{
		var trimmed = rawText.Trim().ToLowerInvariant();
		var cut = trimmed.IndexOf('(', StringComparison.Ordinal);
		return (cut >= 0 ? trimmed[..cut] : trimmed).Trim();
	}

	private static string StateName(FoodState state) => state.ToString();

	private static FoodState CombinedStateTokens(string description)
	{
		var tokens = new List<string>();
		var normalized = TokensFromDescription(description);
		tokens.AddRange(normalized);
		return FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);
	}

	private static IReadOnlyList<string> TokensFromDescription(string description)
	{
		return [];
	}

	private IReadOnlyList<string> NormalizeTokens(string? description)
	{
		var tokens = _normalizer.NormalizeToTokens(description);
		var result = new List<string>(tokens.Count);
		foreach (var token in tokens)
		{
			result.Add(IngredientLineResolver.SingularizeToken(token));
		}

		return result;
	}

	private static bool HeadsAgree(IReadOnlyList<string> keyTokens, IReadOnlyList<string> acceptedTokens)
	{
		if (keyTokens.Count != acceptedTokens.Count)
		{
			return false;
		}

		for (var i = 0; i < keyTokens.Count; i++)
		{
			if (!string.Equals(keyTokens[i], acceptedTokens[i], StringComparison.OrdinalIgnoreCase))
			{
				return false;
			}
		}

		return true;
	}

	private IReadOnlyList<string>? QualifierDiff(IReadOnlyList<string> keyTokens, IReadOnlyList<string> acceptedTokens)
	{
		var keyOnly = new SortedSet<string>(StringComparer.OrdinalIgnoreCase);
		var acceptedOnly = new SortedSet<string>(StringComparer.OrdinalIgnoreCase);

		var keySet = new HashSet<string>(keyTokens, StringComparer.OrdinalIgnoreCase);
		var acceptedSet = new HashSet<string>(acceptedTokens, StringComparer.OrdinalIgnoreCase);
		foreach (var token in keySet)
		{
			if (!acceptedSet.Contains(token))
			{
				keyOnly.Add(token);
			}
		}

		foreach (var token in acceptedSet)
		{
			if (!keySet.Contains(token))
			{
				acceptedOnly.Add(token);
			}
		}

		return [.. keyOnly, .. acceptedOnly];
	}

	private bool CarriesStateToken(string token)
	{
		_singleTokenScratch[0] = token;
		return FdcLexicon.Default.ModifierWords.Contains(token)
			|| FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}
}

/// <summary>Relation class names used by the census TSV and stderr summary.</summary>
public static class RelationNames
{
	/// <summary>Expected row is empty; nothing was labelled for this line.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Can/jar unit present; key row is Canned, accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Key head phrase is compound (2+ words); parsedName equals only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Heads agree; state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Heads and state agree; dataset tiers differ (row chosen at the wrong tier).</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Heads, state and tier agree; qualifier differs.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Heads differ after singularising.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Catch-all for unclassifiable lines.</summary>
	public const string Other = "other";
}
