{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.AutoWrongCensus.Services;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Reads a HoldoutGate debug/batch trace and emits the auto-wrong census TSV, or the P12.7
/// window compound/other pairs TSV. Writes the relation × site summary to the error sink.
/// </summary>
public sealed class AutoWrongCensusRunner : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly AutoWrongClassifier _classifier;
	private readonly ExactOverrideKeyIndex _overrideKeys;
	private readonly TextWriter _output;
	private readonly TextWriter _error;

	private const string TraceSetDebug = "debug";

	private const string TraceSetBatch = "batch";

	private const string CensusHeader =
		"holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";

	private const string PairsHeader = "holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText";

	private const string Window_BLOCKER = "window";

	private const string RouteCompound = "compound";

	private const string RouteOther = "other";

	public AutoWrongCensusRunner(
		AutoWrongClassifier classifier,
		ExactOverrideKeyIndex overrideKeys,
		TextWriter output,
		TextWriter error)
	{
		ArgumentNullException.ThrowIfNull(classifier);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		ArgumentNullException.ThrowIfNull(output);
		ArgumentNullException.ThrowIfNull(error);
		_classifier = classifier;
		_overrideKeys = overrideKeys;
		_output = output;
		_error = error;
	}

	/// <summary>Runs the census or pairs subcommand and returns the process exit code.</summary>
	/// <param name="args">The parsed options.</param>
	/// <param name="cancellationToken">Cancellation token.</param>
	/// <returns>0 on success, 1 on a missing file, refused set, or unusable invocation.</returns>
	public async Task<int> RunAsync(AutoWrongCensusOptions options, CancellationToken cancellationToken = default)
	{
		if (string.IsNullOrWhiteSpace(options.Command))
		{
			AutoWrongCensusUsage.Print();
			return 1;
		}

		if (string.Equals(options.Command, Options.CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase))
		{
			return await RunCensusAsync(options.TracePath, cancellationToken).ConfigureAwait(false);
		}

		if (string.Equals(options.Command, Options.CommandLineArgumentParser.PairsCommand, StringComparison.OrdinalIgnoreCase))
		{
			return await RunPairsAsync(options.CensusTsvPath, options.TracePath, cancellationToken).ConfigureAwait(false);
		}

		AutoWrongCensusUsage.Print();
		return 1;
	}

	private async Task<int> RunCensusAsync(string tracePath, CancellationToken cancellationToken)
	{
		if (!File.Exists(tracePath))
		{
			_error.WriteLine($"census: trace file not found: {tracePath}");
			return 1;
		}

		var lines = await File.ReadAllLinesAsync(tracePath, cancellationToken).ConfigureAwait(false);
		var records = new List<TraceLine>(lines.Count);
		foreach (var line in lines)
		{
			if (string.IsNullOrWhiteSpace(line))
			{
				continue;
			}

			var record = JsonSerializer.Deserialize<TraceLine>(line, JsonOptions);
			if (record is null)
			{
				_error.WriteLine($"census: failed to parse trace line: {line}");
				return 1;
			}

			if (!AllowedSets.Contains(record.Set))
			{
				_error.WriteLine($"census: refused trace set '{record.Set}' (D-029) at {record.HoldoutId}#{record.LineIndex}");
				return 1;
			}

			records.Add(record);
		}

		var autoWrong = records.Where(r => r.Auto && !r.Correct).ToList();
		_output.WriteLine(CensusHeader);

		var counts = new Dictionary<(string Relation, string Site), int>();
		var missingFields = new Dictionary<string, int>();
		var qualifierDiffs = new List<string>();
		var tierDirection = new Dictionary<string, int>();

		foreach (var record in autoWrong)
		{
			var result = _classifier.Classify(record);
			if (string.IsNullOrEmpty(result.Site))
			{
				_error.WriteLine($"census: unknown decision site for {record.HoldoutId}#{record.LineIndex}");
				return 1;
			}

			if (!string.IsNullOrEmpty(result.MissingField))
			{
				missingFields[result.MissingField] = missingFields.GetValueOrDefault(result.MissingField) + 1;
			}

			if (result.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier)
			{
				qualifierDiffs.Add($"{record.HoldoutId}#{record.LineIndex} key=[{result.KeyDesc}] accepted=[{result.AcceptedDesc}] keyOnly=[{string.Join(',', result.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(',', result.AcceptedOnlyQualifiers ?? [])}]");
			}

			if (result.Relation == AutoWrongClassifier.RelationRowChoiceTier)
			{
				tierDirection[$"{result.KeyTier}:{result.AcceptedTier}"] = tierDirection.GetValueOrDefault($"{result.KeyTier}:{result.AcceptedTier}") + 1;
			}

			_counts[(result.Relation, result.Site)] = _counts.GetValueOrDefault((result.Relation, result.Site)) + 1;

			_output.WriteLine(string.Join('\t', new[]
			{
				result.HoldoutId,
				result.LineIndex.ToString(),
				result.Set,
				result.Relation,
				result.Site,
				result.OverrideKey,
				result.AcceptedTier,
				result.KeyTier,
				result.AcceptedState,
				result.KeyState,
				result.ParsedName,
				result.KeyHead,
				result.AcceptedDesc,
				result.KeyDesc,
				result.RawText,
			}));
		}

		WriteSummary(_error, records, autoWrong, missingFields, qualifierDiffs, tierDirection);

		return 0;
	}

	private static readonly HashSet<string> AllowedSets = new(StringComparer.Ordinal) { TraceSetDebug, TraceSetBatch };

	private readonly Dictionary<(string Relation, string Site), int> _counts = new();

	private async Task<int> RunPairsAsync(string censusTsvPath, string tracePath, CancellationToken cancellationToken)
	{
		if (!File.Exists(censusTsvPath) || !File.Exists(tracePath))
		{
			_error.WriteLine("pairs: census TSV or trace file not found");
			return 1;
		}

		var rows = new List<string[]>();
		foreach (var line in await File.ReadAllLinesAsync(censusTsvPath, cancellationToken).ConfigureAwait(false))
		{
			if (string.IsNullOrWhiteSpace(line) || line.StartsWith("holdoutId\t", StringComparison.Ordinal))
			{
				continue;
			}

			var cells = line.Split('\t');
			var blocker = cells.FirstOrDefault(c => c.Equals("blocker", StringComparison.OrdinalIgnoreCase));
			var route = cells.FirstOrDefault(c => c.Equals("route", StringComparison.OrdinalIgnoreCase));
			var holdoutId = cells.FirstOrDefault(c => c.Equals("holdoutId", StringComparison.OrdinalIgnoreCase));
			var lineIndex = cells.FirstOrDefault(c => c.Equals("lineIndex", StringComparison.OrdinalIgnoreCase));
			if (blocker.IsNullOrEmpty || route.IsNullOrEmpty)
			{
				continue;
			}

			if (!string.Equals(blocker, WINDOW_BLOCKER, StringComparison.OrdinalIgnoreCase)
				|| !string.Equals(route, RouteCompound, StringComparison.OrdinalIgnoreCase)
				&& !string.Equals(route, RouteOther, StringComparison.OrdinalIgnoreCase))
			{
				continue;
			}

			if (string.IsNullOrWhiteSpace(holdoutId) || string.IsNullOrWhiteSpace(lineIndex))
			{
				continue;
			}

			rows.Add([holdoutId, lineIndex]);
		}

		var pairs = new List<string>();
		foreach (var (holdoutId, lineIndex) in rows)
		{
			var record = await FindTraceRecordAsync(tracePath, holdoutId, lineIndex, cancellationToken).ConfigureAwait(false);
			if (record is null)
			{
				continue;
			}

			var atom = _classifier.ChooseAtomForTests(record);
			var keyTokens = _classifier.NormalizeTokensForTests(record.ExpectedDescriptions);
			var keyHead = _classifier.KeyHeadPhraseForTests(keyTokens);
			pairs.Add($"{holdoutId}\t{lineIndex}\t{string.Join(' ', SingularTokens(_classifier.NormalizeTokensForTests(atom.ParsedName)))}\t{string.Join(' ', keyHead)}\t{record.RawText}");
		}

		_output.WriteLine(PairsHeader);
		foreach (var pair in pairs)
		{
			_output.WriteLine(pair);
		}

		return 0;
	}

	private async Task<TraceLine?> FindTraceRecordAsync(string tracePath, string holdoutId, string lineIndex, CancellationToken cancellationToken)
	{
		var wanted = int.Parse(lineIndex, CultureInfo.InvariantCulture);
		foreach (var line in await File.ReadAllLinesAsync(tracePath, cancellationToken).ConfigureAwait(false))
		{
			if (string.IsNullOrWhiteSpace(line))
			{
				continue;
			}

			var record = JsonSerializer.Deserialize<TraceLine>(line, JsonOptions);
			if (record is null || !record.HoldoutId.Equals(holdoutId, StringComparison.OrdinalIgnoreCase) || record.LineIndex != wanted)
			{
				continue;
			}

			return record;
		}

		return null;
	}

	private void WriteSummary(
		TextWriter error,
		List<TraceLine> records,
		List<TraceLine> autoWrong,
		Dictionary<string, int> missingFields,
		List<string> qualifierDiffs,
		Dictionary<string, int> tierDirection)
	{
		var relationCounts = new Dictionary<string, int>();
		var siteCounts = new Dictionary<string, int>();
		foreach (var key in _counts)
		{
			relationCounts[key.Key.Relation] = relationCounts.GetValueOrDefault(key.Key.Relation) + key.Value;
			siteCounts[key.Key.Site] = siteCounts.GetValueOrDefault(key.Key.Site) + key.Value;
		}

		error.WriteLine($"autoWrongCensus set={records[0].Set} lines={records.Count} autoWrong={autoWrong.Count}");
		error.WriteLine("relation\tsite\tcount");
		foreach (var key in _counts.OrderBy(k => k.Key.Relation).ThenBy(k => k.Key.Site))
		{
			error.WriteLine($"{key.Key.Relation}\t{key.Key.Site}\t{key.Value}");
		}

		error.WriteLine($"otherRate={autoWrong.Count == 0 ? 0.0 : (double)relationCounts.GetValueOrDefault(AutoWrongClassifier.RelationOther) / autoWrong.Count:0:F2}");
		error.WriteLine($"missingFields={string.Join(',', missingFields.Select(kv => $"{kv.Key}={kv.Value}"))}");
		error.WriteLine($"qualifierDiffs={qualifierDiffs.Count}");
		foreach (var diff in qualifierDiffs)
		{
			error.WriteLine($"qualifierDiff {diff}");
		}

		error.WriteLine($"tierDirection={string.Join(',', tierDirection.Select(kv => $"{kv.Key}={kv.Value}"))}");

		var reuseShouldReuseFalse = autoWrong.Count == 0 ? 0 : CountReuseShouldReuseFalse(autoWrong);
		error.WriteLine($"reuseShouldReuseFalse={reuseShouldReuseFalse}");
	}

	private int CountReuseShouldReuseFalse(List<TraceLine> autoWrong)
	{
		var falseCount = 0;
		foreach (var record in autoWrong)
		{
			var atom = _classifier.ChooseAtomForTests(record);
			if (atom.LinkedIngredientId is null || !atom.Reused)
			{
				continue;
			}

			if (!IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(atom.ParsedName), atom.LinkedIngredientId))
			{
				falseCount++;
			}
		}

		return falseCount;
	}
}
