	private static HashSet<string> QualifierSet(IReadOnlyList<string> qualifiers) =>
		new(qualifiers.Select(IngredientLineResolver.SingularizeToken), StringComparer.OrdinalIgnoreCase);

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static string[] SingularTokens(IReadOnlyList<string> tokens) =>
		Array.ConvertAll(tokens.ToArray(), IngredientLineResolver.SingularizeToken);

	private static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	private bool IsOverrideKey(string rawText)
	{
		// Production folds the raw text with FdcMatcher.StripFromParenthesis (private; FdcMatcher.cs:165)
		// before the raw-key try: content from the first '(' onward, trimmed, lower-cased. That fold is
		// applied here against the shipped exact-overrides.json keys (brief §4) and is the only text
		// operation in this tool not taken from a production member — it is named in the P12.13 report.
#pragma warning disable CA1308 // Reason: lowercase folding for override-key lookup, parity with FdcMatcher.cs:166.
		var cut = rawText.IndexOf('(', StringComparison.Ordinal);
		var folded = (cut >= 0 ? rawText[..cut] : rawText).Trim().ToLowerInvariant();
#pragma warning restore CA1308
		return _overrideKeys.IsKey(folded);
	}

	private bool CarriesStateToken(string token)
	{
		_singleToken[0] = token;
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}
}
