{"content":"using LetUsCook.AutoWrongCensus.Options;

using Shouldly;

using Xunit;

namespace LetUsCook.AutoWrongCensus.Tests.Options;

public sealed class CommandLineArgumentParserTests
{
	[Fact]
	public void ParseMapsCensusSubcommandWithTracePath()
	{
		var result = CommandLineArgumentParser.Parse(["census", "/tmp/base-debug.jsonl"]);

		result[$"{AutoWrongCensusOptions.SectionName}:{nameof(AutoWrongCensusOptions.Command)}"].ShouldBe("census");
		result[$"{AutoWrongCensusOptions.SectionName}:{nameof(AutoWrongCensusOptions.TracePath)}"].ShouldBe("/tmp/base-debug.jsonl");
	}

	[Fact]
	public void ParseMapsPairsSubcommandWithCensusAndTrace()
	{
		var result = CommandLineArgumentParser.Parse(["pairs", "/tmp/census-debug.tsv", "/tmp/base-debug.jsonl"]);

		result[$"{AutoWrongCensusOptions.SectionName}:{nameof(AutoWrongCensusOptions.Command)}"].ShouldBe("pairs");
		result[$"{AutoWrongCensusOptions.SectionName}:{nameof(AutoWrongCensusOptions.CensusTsvPath)}"].ShouldBe("/tmp/census-debug.tsv");
		result[$"{AutoWrongCensusOptions.SectionName}:{nameof(AutoWrongCensusOptions.TracePath)}"].ShouldBe("/tmp/base-debug.jsonl");
	}

	[Fact]
	public void ParseReturnsEmptyDictionaryForUnknownSubcommand()
	{
		var result = CommandLineArgumentParser.Parse(["frobnicate", "/tmp/base-debug.jsonl"]);

		result.ShouldBeEmpty();
	}
}
