{"content":"namespace LetUsCook.AutoWrongCensus.Tests;

/// <summary>Builds trace lines shaped like the real HoldoutGate trace records.</summary>
public static class TraceLineFactory
{
	/// <summary>Creates a trace line with the given facts.</summary>
	public static TraceLine Line(
		string rawText,
		string holdoutId,
		int lineIndex,
		string set = "debug",
		bool auto = true,
		bool correct = false,
		IReadOnlyList<string>? expectedDescriptions = null,
		IReadOnlyList<string>? expectedDataTypes = null,
		IReadOnlyList<string>? actualDescriptions = null,
		IReadOnlyList<string>? actualDataTypes = null,
		params TraceAtom[] atoms) =>
		new TraceLine
		{
			RawText = rawText,
			HoldoutId = holdoutId,
			LineIndex = lineIndex,
			Set = set,
			Auto = auto,
			Correct = correct,
			ExpectedDescriptions = expectedDescriptions ?? [],
			ExpectedDataTypes = expectedDataTypes ?? [],
			ActualDescriptions = actualDescriptions ?? [],
			ActualDataTypes = actualDataTypes ?? [],
			Atoms = atoms.Length > 0 ? atoms : [new TraceAtom { Path = "ranker", Reused = true, ParsedName = rawText, Outcome = "accepted" }],
		};
}
