{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.AutoWrongCensus.Services;

using Shouldly;

using Xunit;

namespace LetUsCook.AutoWrongCensus.Tests.Services;

/// <summary>
/// The console contract through <see cref="AutoWrongCensusCli.RunAsync"/>: exit codes, refusals, and the
/// golden TSV. The golden test writes a trace through the real entry point and compares the full TSV.
/// </summary>
public sealed class AutoWrongCensusRunnerTests
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	[Fact]
	public async Task RunAsyncReturnsZeroOnHelpAsync()
	{
		(await AutoWrongCensusCli.RunAsync(["--help"])).ShouldBe(0);
	}

	[Fact]
	public async Task RunAsyncReturnsOneAndRefusesAMissingTraceAsync()
	{
		var output = new StringWriter();
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["census", "/definitely/not/a/trace.jsonl"], output, error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("refused: trace");
		output.ToString().ShouldBeEmpty();
	}

	[Fact]
	public async Task RunAsyncRefusesASealedTraceSetAsync()
	{
		var tracePath = WriteTrace(["{\"rawText\":\"Kosher salt\",\"holdoutId\":\"debug:sealed-x\",\"lineIndex\":0,\"set\":\"sealed\",\"auto\":true,\"correct\":false,\"expectedDescriptions\":[\"Salt, table, iodized\"],\"expectedDataTypes\":[\"Foundation\"],\"actualDescriptions\":[\"Salt, table, iodized\"],\"actualDataTypes\":[\"Foundation\"],\"atoms\":[]}"]);

		var output = new StringWriter();
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["census", tracePath], output, error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("D-029");
		output.ToString().ShouldBeEmpty();
	}

	[Fact]
	public async Task RunAsyncRefusesAnUnknownTraceSetAsync()
	{
		var tracePath = WriteTrace(["{\"rawText\":\"Kosher salt\",\"holdoutId\":\"debug:holdout-x\",\"lineIndex\":0,\"set\":\"holdout\",\"auto\":true,\"correct\":false,\"expectedDescriptions\":[\"Salt, table, iodized\"],\"expectedDataTypes\":[\"Foundation\"],\"actualDescriptions\":[\"Salt, table, iodized\"],\"actualDataTypes\":[\"Foundation\"],\"atoms\":[]}"]);

		var output = new StringWriter();
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["census", tracePath], output, error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("D-029");
	}

	[Fact]
	public async Task RunAsyncReturnsOneForAnUnusableInvocationAsync()
	{
		var output = new StringWriter();
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["census"], output, error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("usage:");
	}

	[Fact]
	public async Task CensusWritesTheGoldenTsvThroughTheConsoleEntryPointAsync()
	{
		var tracePath = WriteTrace(
		[
			"{\"rawText\":\"1 (28 ounce) can crushed tomatoes\",\"holdoutId\":\"debug:fixture-canned\",\"lineIndex\":0,\"set\":\"debug\",\"auto\":true,\"correct\":false,\"expectedDescriptions\":[\"Tomatoes, crushed, canned\"],\"expectedDataTypes\":[\"Foundation\"],\"actualDescriptions\":[\"Tomato, roma\"],\"actualDataTypes\":[\"Foundation\"],\"atoms\":[{\"path\":\"ranker\",\"reused\":true,\"parsedName\":\"tomatoes\",\"linkedIngredientId\":\"tomato\",\"outcome\":\"accepted\"}]}",
			"{\"rawText\":\"3 cups bread crumbs, or as needed\",\"holdoutId\":\"debug:fixture-bread\",\"lineIndex\":0,\"set\":\"debug\",\"auto\":true,\"correct\":false,\"expectedDescriptions\":[\"Bread, crumbs, dry, grated, plain\"],\"expectedDataTypes\":[\"SrLegacy\"],\"actualDescriptions\":[\"Bread, white, commercially prepared (includes soft bread crumbs)\"],\"actualDataTypes\":[\"SrLegacy\"],\"atoms\":[{\"path\":\"override\",\"reused\":true,\"parsedName\":\"bread\",\"linkedIngredientId\":\"bread\",\"outcome\":\"accepted\"}]}",
			"{\"rawText\":\"1/2 cup finely chopped blanched almonds\",\"holdoutId\":\"debug:fixture-almonds\",\"lineIndex\":0,\"set\":\"debug\",\"auto\":true,\"correct\":false,\"expectedDescriptions\":[\"Nuts, almonds, blanched\"],\"expectedDataTypes\":[\"SrLegacy\"],\"actualDescriptions\":[\"Nuts, almonds, whole, raw\"],\"actualDataTypes\":[\"Foundation\"],\"atoms\":[{\"path\":\"ranker\",\"reused\":true,\"parsedName\":\"almonds\",\"linkedIngredientId\":\"almond\",\"outcome\":\"accepted\"}]}",
			"{\"rawText\":\"2 carrots, chopped\",\"holdoutId\":\"debug:fixture-carrots\",\"lineIndex\":0,\"set\":\"debug\",\"auto\":true,\"correct\":false,\"expectedDescriptions\":[\"Carrots, raw\"],\"expectedDataTypes\":[\"SrLegacy\"],\"actualDescriptions\":[\"Carrots, raw\"],\"actualDataTypes\":[\"Foundation\"],\"atoms\":[{\"path\":\"ranker\",\"reused\":true,\"parsedName\":\"carrots\",\"linkedIngredientId\":\"carrot\",\"outcome\":\"accepted\"}]}",
			"{\"rawText\":\"1 cup 2% milk\",\"holdoutId\":\"debug:fixture-milk\",\"lineIndex\":0,\"set\":\"debug\",\"auto\":true,\"correct\":false,\"expectedDescriptions\":[\"Milk, low fat, with calcium added\"],\"expectedDataTypes\":[\"SrLegacy\"],\"actualDescriptions\":[\"Milk, low fat\"],\"actualDataTypes\":[\"SrLegacy\"],\"atoms\":[{\"path\":\"ranker\",\"reused\":false,\"parsedName\":\"low fat milk\",\"linkedIngredientId\":null,\"outcome\":\"accepted\"}]}",
			"{\"rawText\":\"1 onion, diced\",\"holdoutId\":\"debug:fixture-onion\",\"lineIndex\":0,\"set\":\"debug\",\"auto\":true,\"correct\":false,\"expectedDescriptions\":[\"Onions, raw\"],\"expectedDataTypes\":[\"SrLegacy\"],\"actualDescriptions\":[\"Garlic, raw\"],\"actualDataTypes\":[\"Foundation\"],\"atoms\":[{\"path\":\"override\",\"reused\":false,\"parsedName\":\"onion\",\"linkedIngredientId\":null,\"outcome\":\"accepted\"}]}",
			"{\"rawText\":\"2 stalks celery\",\"holdoutId\":\"debug:fixture-celery\",\"lineIndex\":0,\"set\":\"debug\",\"auto\":true,\"correct\":false,\"expectedDescriptions\":[\"Celery, leaves\"],\"expectedDataTypes\":[\"SrLegacy\"],\"actualDescriptions\":[\"Celery\"],\"actualDataTypes\":[],\"atoms\":[{\"path\":\"ranker\",\"reused\":true,\"parsedName\":\"celery leaves\",\"linkedIngredientId\":null,\"outcome\":\"accepted\"}]}",
			"{\"rawText\":\"1 (4 ounce) jar apricot baby food\",\"holdoutId\":\"debug:fixture-jar\",\"lineIndex\":0,\"set\":\"debug\",\"auto\":true,\"correct\":false,\"expectedDescriptions\":[\"Apricots, canned, drained, packed in heavy syrup, sweetened\"],\"expectedDataTypes\":[\"Branded\"],\"actualDescriptions\":[\"Apricots, raw\"],\"actualDataTypes\":[\"SrLegacy\"],\"atoms\":[{\"path\":\"ranker\",\"reused\":true,\"parsedName\":\"apricots\",\"linkedIngredientId\":\"apricot\",\"outcome\":\"accepted\"}]}",
			"{\"rawText\":\"amaretto\",\"holdoutId\":\"debug:fixture-amaretto\",\"lineIndex =0,\"set\":\"debug\",\"auto\":true,\"correct\":false,\"expectedDescriptions\":[\"Cherries, sour, red\"],\"expectedDataTypes\":[\"SrLegacy\"],\"actualDescriptions\":[\"Cherries, sour, maraschino, glazed\"],\"actualDataTypes\":[\"SrLegacy\"],\"atoms\":[{\"path\":\"override\",\"reused\":true,\"parsedName\":\"amaretto\",\"linkedIngredientId\":\"cherry\",\"outcome\":\"accepted\"}]}",
			"{\"rawText\":\"2 tsp good olive oil\",\"holdoutId\":\"debug:fixture-nolabel\",\"lineIndex\":0,\"set\":\"debug\",\"auto\":true,\"correct\":false,\"expectedDescriptions\":[],\"expectedDataTypes\":[],\"actualDescriptions\":[\"Oil, olive, salad or cooking\"],\"actualDataTypes\":[\"SrLegacy\"],\"atoms\":[{\"path\":\"curated\",\"reused\":true,\"parsedName\":\"olive oil\",\"linkedIngredientId\":null,\"outcome\":\"accepted\"}]}",
		]);

		var output = new StringWriter();
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["census", tracePath], output, error);

		exit.ShouldBe(0);
		var actual = output.ToString();
		var expected = "holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText\r\n"
			+ "debug:fixture-canned\t0\tdebug\tpack-unit-state\treuse\t\tFoundation\tFoundation\tNone\tCanned\ttomatoes\ttomato crushed\tTomato, roma\tTomatoes, crushed, canned\t1 (28 ounce) can crushed tomatoes\r\n"
			+ "debug:fixture-bread\t0\tdebug\tcompound-head-lost\toverride\tno\tSrLegacy\tSrLegacy\tNone\tDried\tbread\tbread crumb\tBread, white, commercially prepared (includes soft bread crumbs)\tBread, crumbs, dry, grated, plain\t3 cups bread crumbs, or as needed\r\n"
			+ "debug:fixture-almonds\t0\tdebug\tstate-mismatch\treuse\t\tFoundation\tSrLegacy\tRaw\tNone\talmonds\tnut almond blanched\tNuts, almonds, whole, raw\tNuts, almonds, blanched\t1/2 cup finely chopped blanched almonds\r\n"
			+ "debug:fixture-carrots\t0\tdebug\trow-choice-tier\treuse\t\tFoundation\tSrLegacy\tRaw\tRaw\tcarrots\tcarrot\tCarrots, raw\tCarrots, raw\t2 carrots, chopped\r\n"
			+ "debug:fixture-milk\t0\tdebug\tsame-head-other-qualifier\tranker\t\tSrLegacy\tSrLegacy\tNone\tNone\tlow fat milk\tmilk\tMilk, low fat\tMilk, low fat, with calcium added\t1 cup 2% milk\r\n"
			+ "debug:fixture-onion\t0\tdebug\tsibling-food\toverride\tno\tFoundation\tSrLegacy\tNone\tNone\tonion\tonion\tGarlic, raw\tOnions, raw\t1 onion, diced\r\n"
			+ "debug:fixture-celery\t0\tdebug\tother\tranker\t\t\tSrLegacy\tNone\tNone\tcelery leaves\tcelery\tCelery\tCelery, leaves\t2 stalks celery\r\n"
			+ "debug:fixture-jar\t0\tdebug\tpack-unit-state\treuse\t\tSrLegacy\tBranded\tNone\tCanned\tapricots\tapricot\tApricots, raw\tApricots, canned, drained, packed in heavy syrup, sweetened\t1 (4 ounce) jar apricot baby food\r\n"
			+ "debug:fixture-amaretto\t0\tdebug\trow-choice-tier\toverride\tyes\tSrLegacy\tSrLegacy\tNone\tNone\tamaretto\tcherry\tCherries, sour, maraschino, glazed\tCherries, sour, red\tamaretto\r\n"
			+ "debug:fixture-nolabel\t0\tdebug\tno-label\tcurated\t\tSrLegacy\t\tNone\tNone\tolive oil\tolive oil\tOil, olive, salad or cooking\t\t2 tsp good olive oil\r\n";
		actual.ShouldBe(expected);
	}

	[Fact]
	public async Task PairsEmitsOnlyWindowCompoundAndOtherCensusRowsAsync()
	{
		var tracePath = WriteTrace(
		[
			"{\"rawText\":\"1 cup bread crumbs\",\"holdoutId\":\"debug:fixture-bread\",\"lineIndex\":0,\"set\":\"debug\",\"auto\":true,\"correct\":false,\"expectedDescriptions\":[\"Bread, crumbs, dry, grated, plain\"],\"expectedDataTypes\":[\"SrLegacy\"],\"actualDescriptions\":[\"Bread, white, commercially prepared\"],\"actualDataTypes\":[\"SrLegacy\"],\"atoms\":[{\"path\":\"override\",\"reused\":true,\"parsedName\":\"bread\",\"linkedIngredientId\":\"bread\",\"outcome\":\"accepted\"}]}",
		]);
		var censusPath = WriteCensus(
			[
				"holdoutId\tlineIndex\tblocker\troute",
				"debug:fixture-bread\t0\twindow\tcompound",
				"debug:fixture-bread\t1\twindow\tother",
				"debug:fixture-bread\t2\tmapping-reuse\tcompound",
				"debug:fixture-bread\t3\twindow\tparser-word-lost",
			]);

		var output = new StringWriter();
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["pairs", censusPath, tracePath], output, error);

		exit.ShouldBe(0);
		var actual = output.ToString();
		actual.ShouldBe("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText\r\n" + "debug:fixture-bread\t0\tbread\tbread crumb\t1 cup bread crumbs\r\n");
	}

	private static string WriteTrace(string[] lines)
	{
		var path = Path.Combine(Path.GetTempPath(), $"autowrong-census-{Guid.NewGuid():N}.jsonl");
		File.WriteAllLines(path, lines);
		return path;
	}

	private static string WriteCensus(string[] lines)
	{
		var path = Path.Combine(Path.GetTempPath(), $"autowrong-census-{Guid.NewGuid():N}.tsv");
		File.WriteAllLines(path, lines);
		return path;
	}
}
