{"content":"using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Services;

using LetUsCook.Fdc.Lexicon;

using Shouldly;

using Xunit;

namespace LetUsCook.AutoWrongCensus.Tests.Services;

/// <summary>
/// Relation and site classification, one fact per class. The inputs are trace records shaped like the
/// real ones; every expectation goes through <see cref="AutoWrongClassifier.Classify"/>, which calls the
/// production matcher helpers — no re-implementation in the test (D-014).
/// </summary>
public sealed class AutoWrongClassifierTests
{
	private static readonly FdcNormalizer Normalizer = new();
	private static readonly ExactOverrideKeyIndex OverrideKeys = new();
	private static readonly AutoWrongClassifier Classifier = new(Normalizer, OverrideKeys);

	[Fact]
	public void ClassifiesTheBriefsCanTomatoesLineAsPackUnitStateAtReuse()
	{
		var line = Line(
			"1 (28 ounce) can crushed tomatoes",
			["Tomatoes, crushed, canned"],
			["Foundation"],
			["Tomato, roma"],
			["Foundation"],
			path: "ranker",
			reused: true,
			parsedName: "tomatoes",
			linked: "tomato");

		var result = Classifier.Classify(line);

		result.Relation.ShouldBe(AutoWrongClassifier.RelationPackUnitState);
		result.Site.ShouldBe(AutoWrongClassifier.SiteReuse);
		result.KeyState.ShouldBe("Canned");
		result.AcceptedState.ShouldBe("None");
		result.OverrideKey.ShouldBe(string.Empty);
	}

	[Fact]
	public void ClassifiesTheBriefsBreadCrumbsLineAsCompoundHeadLostAtOverride()
	{
		var line = Line(
			"3 cups bread crumbs, or as needed",
			["Bread, crumbs, dry, grated, plain"],
			["SrLegacy"],
			["Bread, white, commercially prepared (includes soft bread crumbs)"],
			["SrLegacy"],
			path: "override",
			reused: true,
			parsedName: "bread",
			linked: "bread");

		var result = Classifier.Classify(line);

		result.Relation.ShouldBe(AutoWrongClassifier.RelationCompoundHeadLost);
		result.Site.ShouldBe(AutoWrongClassifier.SiteOverride);
		result.OverrideKey.ShouldBe("no");
		result.KeyHead.ShouldBe("bread crumb");
		result.KeyState.ShouldBe("Dried");
		result.AcceptedState.ShouldBe("None");
	}

	[Fact]
	public void ClassifiesTheBriefsBlanchedAlmondsLineAsStateMismatchAtReuse()
	{
		var line = Line(
			"1/2 cup finely chopped blanched almonds",
			["Nuts, almonds, blanched"],
			["SrLegacy"],
			["Nuts, almonds, whole, raw"],
			["Foundation"],
			path: "ranker",
			reused: true,
			parsedName: "almonds",
			linked: "almond");

		var result = Classifier.Classify(line);

		result.Relation.ShouldBe(AutoWrongClassifier.RelationStateMismatch);
		result.Site.ShouldBe(AutoWrongClassifier.SiteReuse);
		result.AcceptedState.ShouldBe("Raw");
		result.KeyState.ShouldBe("None");
	}

	[Fact]
	public void ClassifiesBlankLabelAsNoLabelAndNamesTheMissingField()
	{
		var line = Line(
			"2 tsp good olive oil",
			[],
			[],
			["Oil, olive, salad or cooking"],
			["SrLegacy"],
			path: "curated",
			reused: true,
			parsedName: "olive oil");

		var result = Classifier.Classify(line);

		result.Relation.ShouldBe(AutoWrongClassifier.RelationNoLabel);
		result.MissingField.ShouldBe("expectedDescriptions");
		result.Site.ShouldBe(AutoWrongClassifier.SiteCurated);
	}

	[Fact]
	public void ClassifiesAgreeingHeadsAndStatesWithDifferentTiersAsRowChoiceTier()
	{
		var line = Line(
			"2 carrots, chopped",
			["Carrots, raw"],
			["SrLegacy"],
			["Carrots, raw"],
			["Foundation"],
			path: "ranker",
			reused: true,
			parsedName: "carrots",
			linked: "carrot");

		var result = Classifier.Classify(line);

		result.Relation.ShouldBe(AutoWrongClassifier.RelationRowChoiceTier);
		result.KeyTier.ShouldBe("SrLegacy");
		result.AcceptedTier.ShouldBe("Foundation");
	}

	[Fact]
	public void ClassifiesHeadsAndStatesAgreeingButMissingAcceptedTierAsOtherAndNamesTheField()
	{
		var line = Line(
			"2 stalks celery",
			["Celery, leaves"],
			["SrLegacy"],
			["Celery"],
			[],
			path: "ranker",
			reused: true,
			parsedName: "celery leaves",
			linked: "celery");

		var result = Classifier.Classify(line);

		result.Relation.ShouldBe(AutoWrongClassifier.RelationOther);
		result.MissingField.ShouldBe("actualDataTypes");
	}

	[Fact]
	public void ClassifiesSameHeadSameStateSameTierWithDifferentQualifiersAndRecordsTheDiff()
	{
		var line = Line(
			"1 cup 2% milk",
			["Milk, low fat, with calcium added"],
			["SrLegacy"],
			["Milk, low fat"],
			["SrLegacy"],
			path: "ranker",
			reused: false,
			parsedName: "low fat milk");

		var result = Classifier.Classify(line);

		result.Relation.ShouldBe(AutoWrongClassifier.RelationSameHeadOtherQualifier);
		result.Site.ShouldBe(AutoWrongClassifier.SiteRanker);
		result.KeyOnlyQualifiers!.ShouldContain("calcium");
		result.AcceptedOnlyQualifiers!.ShouldBeEmpty();
	}

	[Fact]
	public void ClassifiesDifferentHeadTermsAsSiblingFood()
	{
		var line = Line(
			"1 onion, diced",
			["Onions, raw"],
			["SrLegacy"],
			["Garlic, raw"],
			["Foundation"],
			path: "override",
			reused: false,
			parsedName: "onion");

		var result = Classifier.Classify(line);

		result.Relation.ShouldBe(AutoWrongClassifier.RelationSiblingFood);
		result.Site.ShouldBe(AutoWrongClassifier.SiteOverride);
		result.OverrideKey.ShouldBe("no");
	}

	[Fact]
	public void ClassifiesAJarUnitWithACannedKeyAsPackUnitStateEvenWhenTiersAndStateAlsoDiffer()
	{
		var line = Line(
			"1 (4 ounce) jar apricot baby food",
			["Apricots, canned, drained, packed in heavy syrup, sweetened"],
			["Branded"],
			["Apricots, raw"],
			["SrLegacy"],
			path: "ranker",
			reused: true,
			parsedName: "apricots",
			linked: "apricot");

		var result = Classifier.Classify(line);

		result.Relation.ShouldBe(AutoWrongClassifier.RelationPackUnitState);
	}

	[Fact]
	public void MarksAnOverrideLineWhoseFoldedRawTextIsAnExactOverrideKeyAsYes()
	{
		var line = Line(
			"amaretto",
			["Cherries, sour, red"],
			["SrLegacy"],
			["Cherries, sour, maraschino, glazed"],
			["SrLegacy"],
			path: "override",
			reused: true,
			parsedName: "amaretto",
			linked: "cherry");

		var result = Classifier.Classify(line);

		result.Site.ShouldBe(AutoWrongClassifier.SiteOverride);
		result.OverrideKey.ShouldBe("yes");
	}

	[Fact]
	public void MapsUnknownAtomPathToAnEmptySiteSoTheRunnerRefuses()
	{
		var line = Line(
			"1 cup mystery",
			["Rice, white, long grain, enriched, parboiled, cooked"],
			["Survey"],
			["Rice, white, long grain, parboiled, cooked"],
			["Survey"],
			path: "hand-fed",
			reused: false,
			parsedName: "mystery");

		Classifier.Classify(line).Site.ShouldBe(string.Empty);
	}

	[Fact]
	public void OnlyASingleTokenParsedNameTriggersCompoundHeadLost()
	{
		var line = Line(
			"1 cup bread crumbs",
			["Bread, crumbs, dry, grated, plain"],
			["SrLegacy"],
			["Bread, white, commercially prepared (includes soft bread crumbs)"],
			["SrLegacy"],
			path: "override",
			reused: true,
			parsedName: "bread crumbs");

		var result = Classifier.Classify(line);

		result.Relation.ShouldBe(AutoWrongClassifier.RelationStateMismatch);
	}

	[Fact]
	public void HeadPhraseStopsAtTheFirstTokenProductionExtractsStateFrom()
	{
		Classifier.KeyHeadPhrase(Normalizer.NormalizeToTokens("Bread, crumbs, dry, grated, plain"))
			.ShouldBe(["bread", "crumb"]);
		Classifier.KeyHeadPhrase(Normalizer.NormalizeToTokens("Tomatoes, crushed, canned"))
			.ShouldBe(["tomato", "crushed"]);
	}

	[Fact]
	public void ChoosesTheAcceptedAtomWhenTheLineHasSeveral()
	{
		var line = new TraceLine
		{
			RawText = "1 cup crushed tomatoes",
			HoldoutId = "debug:multi-atom",
			LineIndex = 2,
			Set = "debug",
			Auto = true,
			Correct = false,
			ExpectedDescriptions = ["Tomatoes, crushed, canned"],
			ExpectedDataTypes = ["Foundation"],
			ActualDescriptions = ["Tomato, roma"],
			ActualDataTypes = ["Foundation"],
			Atoms = new TraceAtom[]
			{
				new TraceAtom { Path = "override", ParsedName = "water", Outcome = "rejected" },
				new TraceAtom { Path = "ranker", Reused = true, ParsedName = "tomatoes", LinkedIngredientId = "tomato", Outcome = = "accepted" },
			},
		};

		var result = Classifier.Classify(line);

		result.Relation.ShouldBe(AutoWrongClassifier.RelationCompoundHeadLost);
		result.Site.ShouldBe(AutoWrongClassifier.SiteReuse);
	}

	private static TraceLine Line(
		string rawText,
		string[] keyDescriptions,
		string[] keyTypes,
		string[] acceptedDescriptions,
		string[] acceptedTypes,
		string path,
		bool reused,
		string parsedName,
		string? linked = null) =>
		new()
		{
			RawText = rawText,
			HoldoutId = "debug:fixture",
			LineIndex = 0,
			Set = "debug",
			Auto = true,
			Correct = false,
			ExpectedDescriptions = keyDescriptions,
			ExpectedDataTypes = keyTypes,
			ActualDescriptions = acceptedDescriptions,
			ActualDataTypes = acceptedTypes,
			Atoms = new TraceAtom[]
			{
				new TraceAtom { Path = path, Reused = reused, ParsedName = parsedName, LinkedIngredientId = linked, Outcome = "accepted" },
			},
		};
