{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;

using Shouldly;

using Xunit;

namespace LetUsCook.AutoWrongCensus.Tests;

/// <summary>
/// The CLI contract through the real entry point (<see cref="AutoWrongCensusCli.RunAsync"/> → the same
/// host graph <c>Program.cs</c> builds): golden TSV, relation × site summary consistency, set refusal
/// (D-029), missing-input and unknown-path exits.
/// </summary>
public sealed class AutoWrongCensusCliTests
{
	private const string GoldenTsv =
		"holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText\n" +
		"debug:nolabel\t0\tdebug\tno-label\tcurated\t\tSrLegacy\t\tNone\t\tolive oil\t\tOil, olive, salad or cooking\t\t2 tsp good olive oil\n" +
		"debug:canned\t0\tdebug\tpack-unit-state\treuse\t\tFoundation\tFoundation\tNone\tCanned\ttomatoes\ttomato crushed\tTomato, roma\tTomatoes, crushed, canned\t1 (28 ounce) can crushed tomatoes\n" +
		"debug:breadcrumbs\t0\tdebug\tcompound-head-lost\toverride\tno\tSrLegacy\tSrLegacy\tNone\tDried\tbread\tbread crumb\tBread, white, commercially prepared (includes soft bread crumbs)\tBread, crumbs, dry, grated, plain\t3 cups bread crumbs, or as needed\n" +
		"debug:almonds\t0\tdebug\tstate-mismatch\treuse\t\tFoundation\tSrLegacy\tRaw\tNone\talmonds\tnut almond blanched\tNuts, almonds, whole, raw\tNuts, almonds, blanched\t1/2 cup finely chopped blanched almonds\n" +
		"debug:tier\t0\tdebug\trow-choice-tier\treuse\t\tFoundation\tSrLegacy\tRaw\tRaw\tcarrots\tcarrot\tCarrots, raw\tCarrots, raw\t2 carrots, chopped\n" +
		"debug:qualifier\t0\tdebug\tsame-head-other-qualifier\tranker\t\tSrLegacy\tSrLegacy\tNone\tNone\tlow fat milk\tmilk\tMilk, low fat\tMilk, low fat, with calcium added\t1 cup 2% milk\n" +
		"debug:sibling\t0\tdebug\tsibling-food\toverride\tno\tFoundation\tSrLegacy\tRaw\tRaw\tonion\tonion\tGarlic, raw\tOnions, raw\t1 onion, diced\n" +
		"debug:missingtier\t0\tdebug\tother\treuse\t\t\tSrLegacy\t\t\tcelery leaves\tcelery leaf\tCelery\tCelery, leaves\t2 stalks celery\n" +
		"debug:jar\t0\tdebug\tpack-unit-state\treuse\t\tSrLegacy\tBranded\tNone\tCanned\tapricots\tapricot\tApricots, raw\tApricots, canned, drained, packed in heavy syrup, sweetened\t1 (4 ounce) jar apricot baby food\n" +
		"debug:amaretto\t0\tdebug\tsame-head-other-qualifier\toverride\tyes\tSrLegacy\tSrLegacy\tNone\tNone\tamaretto\tcherry\tCherries, sour, maraschino, glazed\tCherries, sour, red\tamaretto\n";

	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	[Fact]
	public async Task CensusWritesTheGoldenTsvThroughTheConsoleEntryPointAsync()
	{
		var tracePath = WriteTrace(BuildCensusFixture());

		using var output = new StringWriter();
		using var error = new StringWriter();
		var exit = await AutoWrongCensusCli.RunAsync(["census", tracePath], output, error);

		exit.ShouldBe(0);
		output.ToString().ReplaceLineEndings("\n").ShouldBe(GoldenTsv);
	}

	[Fact]
	public async Task CensusSummaryMatrixEqualsTheWrittenTsvCellsAsync()
	{
		var tracePath = WriteTrace(BuildCensusFixture());

		using var output = new StringWriter();
		using var error = new StringWriter();
		await AutoWrongCensusCli.RunAsync(["census", tracePath], output, error);

		var tsvLines = output.ToString().ReplaceLineEndings("\n").TrimEnd('\n').Split('\n').Skip(1).ToArray();
		var expectedCounts = tsvLines
			.Select(l => l.Split('\t'))
			.GroupBy(cells => (cells[3], cells[4]))
			.ToDictionary(g => g.Key, g => g.Count());

		var matrix = error.ToString().ReplaceLineEndings("\n").TrimEnd('\n').Split('\n')
			.SkipWhile(l => l != "relation\tsite\tcount")
			.Skip(1)
			.TakeWhile(l => l.Contains('\t', StringComparison.Ordinal))
			.Select(l => l.Split('\t'))
			.Select(cells => ((string)cells[0], (string)cells[1], int.Parse(cells[2], System.Globalization.CultureInfo.InvariantCulture)))
			.ToDictionary(t => (t.Item1, t.Item2), t => t.Item3);
		foreach (var entry in expectedCounts)
		{
			matrix.ShouldContainKeyAndValue((entry.Key.Item1, entry.Key.Item2), entry.Value);
		}

		error.ToString().ShouldContain($"autoWrongCensus traced={tsvLines.Length} autoWrong={tsvLines.Length}");
		error.ToString().ShouldContain("other=0/");
	}

	[Fact]
	public async Task CensusRefusesAMissingTraceWithExitOneAsync()
	{
		using var output = new StringWriter();
		using var error = new StringWriter();
		var exit = await AutoWrongCensusCli.RunAsync(["census", "/nonexistent/autowrong-trace.jsonl"], output, error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("not found");
		output.ToString().ShouldBeEmpty();
	}

	[Fact]
	public async Task CensusRefusesASealedTraceWithoutWritingAnyTsvAsync()
	{
		var line = Line("debug:keep", "sealed");
		var tracePath = WriteTrace([JsonSerializer.Serialize(line, JsonOptions)]);

		using var output = new StringWriter();
		using var error = new StringWriter();
		var exit = await AutoWrongCensusCli.RunAsync(["census", tracePath], output, error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("refused: set 'sealed'");
		error.ToString().ShouldContain("D-029");
		output.ToString().ShouldBeEmpty();
	}

	[Fact]
	public async Task CensusRefusesASetOtherThanDebugOrBatchAsync()
	{
		var line = Line("debug:keep", "sealed-holdout");
		var tracePath = WriteTrace([JsonSerializer.Serialize(line, JsonOptions)]);

		var exit = await AutoWrongCensusCli.RunAsync(["census", tracePath], new StringWriter(), new StringWriter());

		exit.ShouldBe(1);
	}

	[Fact]
	public async Task CensusRefusesAnUnknownAtomPathInsteadOfSilentlySkippingTheLineAsync()
	{
		var line = Line("debug:keep", "debug") with { Atoms = [new TraceAtom { Path = "hand-fed", ParsedName = "something", Outcome = "accepted" }] };
		var tracePath = WriteTrace([JsonSerializer.Serialize(line, JsonOptions)]);

		using var output = new StringWriter();
		using var error = new StringWriter();
		var exit = await AutoWrongCensusCli.RunAsync(["census", tracePath], output, error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("hand-fed");
		output.ToString().ShouldBeEmpty();
	}

	[Fact]
	public async Task CensusIgnoresAutoCorrectAndManualLinesAsync()
	{
		var autoWrong = Line("debug:wrong", "debug");
		var autoCorrect = Line("debug:right", "debug") with { Correct = true };
		var manual = Line("debug:manual", "debug") with { Auto = false };
		var tracePath = WriteTrace([autoWrong, autoCorrect, manual].Select(l => JsonSerializer.Serialize(l, JsonOptions)));

		using var output = new StringWriter();
		await AutoWrongCensusCli.RunAsync(["census", tracePath], output, new StringWriter());

		var lines = output.ToString().ReplaceLineEndings("\n").TrimEnd('\n').Split('\n');
		lines.Length.ShouldBe(2);
		lines[0].ShouldBe("debug:wrong");
		lines[1].ShouldBe("debug:wrong");
	}

	[Fact]
	public async Task RunAsyncPrintsUsageAndReturnsOneOnUnusableArgumentsAsync()
	{
		var cases = new[]
		{
			Array.Empty<string>(),
			["census"],
			["census", "a.jsonl", "extra"],
			["pairs", "c.tsv"],
			["widen", "a.jsonl"],
		};

		foreach (var args in cases)
		{
			using var error = new StringWriter();
			var exit = await AutoWrongCensusCli.RunAsync(args, new StringWriter(), error);
			exit.ShouldBe(1, $"{args.Length} args");
			error.ToString().ShouldContain("usage:");
		}
	}

	[Fact]
	public async Task HelpReturnsZeroAsync()
	{
		(await AutoWrongCensusCli.RunAsync(["--help"])).ShouldBe(0);
		(await AutoWrongCensusCli.RunAsync(["-h"])).ShouldBe(0);
	}

	[Fact]
	public async Task PairsEmitsOnlyWindowRowsWithRouteCompoundOrOtherAsync()
	{
		var censusPath = WriteText([
			"holdoutId\tlineIndex\tblocker\troute",
			"debug:a\t0\twindow\tcompound",
			"debug:a\t1\twindow\tother",
			"debug:a\t2\tmapping-reuse\tcompound",
			"debug:a\t3\twindow\tparser-word-lost",
			"debug:b\t9\twindow\tcompound",
		]);
		var trace = new[]
		{
			Line("debug:a", "debug") with { LineIndex = 0 },
			Line("debug:a", "debug") with { LineIndex = 1 },
			Line("debug:a", "debug") with { LineIndex = 2 },
			Line("debug:a", "debug") with { LineIndex = 3 },
		};
		var tracePath = WriteTrace(trace.Select(l => JsonSerializer.Serialize(l, JsonOptions)));

		using var output = new StringWriter();
		using var error = new StringWriter();
		var exit = await AutoWrongCensusCli.RunAsync(["pairs", censusPath, tracePath], output, error);

		exit.ShouldBe(0);
		var lines = output.ToString().ReplaceLineEndings("\n").TrimEnd('\n').Split('\n');
		lines.Length.ShouldBe(3);
		lines[0].ShouldBe("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		lines[1].ShouldStartWith("debug:a\t0\t");
		lines[2].ShouldStartWith("debug:a\t1\t");
		output.ToString().ShouldNotContain("debug:a\t2");
		output.ToString().ShouldNotContain("debug:a\t3");
		error.ToString().ShouldContain("pairs emitted=2 unmatchedCensusRows=1");
	}

	[Fact]
	public async Task PairsRefusesAMissingCensusTsvAsync()
	{
		var tracePath = WriteTrace([Line("debug:a", "debug")]);

		var exit = await AutoWrongCensusCli.RunAsync(["pairs", "/nonexistent/census.tsv", tracePath], new StringWriter(), new StringWriter());

		exit.ShouldBe(1);
	}

