{"content":"import csv, re, json, sys

REL = {'pack-unit-state','compound-head-lost','state-mismatch','row-choice-tier',
       'same-head-other-qualifier','sibling-food','no-label','other'}
SITE = {'override','reuse','ranker','curated'}

def tokens(s):
    return re.findall(r"[a-z0-9]+(?:-[a-z0-9]+)*", s.lower())

def sing_forms(t):
    t = t.lower().strip()
    out = {t}
    if t.endswith('s') and not t.endswith('ss') and not t.endswith('us') and not t.endswith('is'):
        out.add(t[:-1])
    if t.endswith('es') and not t.endswith('ss'):
        out.add(t[:-2])
    return out

def head_tail_evidence(keyHead, rawText):
    """Does the singularised normalized rawText contain a token of keyHead[1..]?"""
    head = tokens(keyHead)
    raw = set()
    for t in tokens(rawText):
        raw.update(sing_forms(t))
    for t in head[1:]:
        if t in raw:
            return True
    return False

def run(f):
    rows = list(csv.DictReader(open(f), delimiter='\t'))
    badrel = [r for r in rows if r['relation'] not in REL]
    badsite = [r for r in rows if r['site'] not in SITE]
    other = [r for r in rows if r['relation'] == 'other']
    ch = [r for r in rows if r['relation'] == 'compound-head-lost']
    no_evidence = [r for r in ch if not head_tail_evidence(r['keyHead'], r['rawText'])]
    print(f, 'rows=', len(rows), 'badrel=', len(badrel), 'badsite=', len(badsite),
          'other=', len(other), 'compound=', len(ch), 'compound_no_head_tail_evidence=', len(no_evidence))
    for r in no_evidence:
        print('   NO-EVIDENCE:', r['holdoutId'], r['lineIndex'], 'keyHead=', r['keyHead'], 'raw=', r['rawText'], 'parsed=', r['parsedName'])
    return rows

d = run('/tmp/p1213f2/autowrong-debug.tsv')
b = run('/tmp/p1213f2/autowrong-batch.tsv')

