import csv, re, json
MAP=json.load(open('/Users/standard.analyst/Code/LetUsCook/src/LetUsCook.Fdc/Lexicon/Resources/singular-map-en.json'))
INV={v:k for k,v in MAP.items()}

def tokens(s):
    return re.findall(r"[a-z0-9]+", s.lower())

def normalized_tokens(s):
    toks=tokens(s)
    out=[]
    i=0
    while i < len(toks):
        # phrase match: longest key in MAP whose tokens appear consecutively
        best=None
        for key in MAP:
            kt=tokens(key)
            if len(kt)>0 and toks[i:i+len(kt)]==kt and (best is None or len(kt)>len(tokens(best))):
                best=key
        if best is None:
            out.append(toks[i]); i+=1
        else:
            out.append(MAP[best]); i+=len(tokens(best))
    return out

def ev_ok(keyHead, raw):
    head=keyHead.split()
    rt=normalized_tokens(raw)
    for t in head[1:]:
        if t in rt: return True
        if t+'s' in rt or t+'es' in rt: return True
        if t.endswith('y') and t[:-1]+'ies' in rt: return True
        if t.endswith('f') and t[:-1]+'ves' in rt: return True
    return False

for f in ('autowrong-debug.tsv','autowrong-batch.tsv'):
